// El webhook de n8n es público (Caddy): solo aceptamos la llamada interna del escenario 1.
const crypto = require('crypto');
const h = $input.first().json.headers || {};
const secret = $env.ERP_API_KEY || '';
const got = h['x-internal-token'] || '';
const ok = secret.length > 0 && got.length === secret.length
  && crypto.timingSafeEqual(Buffer.from(got), Buffer.from(secret));
if (!ok) throw new Error('Llamada rechazada: X-Internal-Token ausente o incorrecto');
const b = $input.first().json.body || {};
return [{ json: { ticket_ref: b.ticket_ref, order_ref: b.order_ref ?? null, customer_name: b.customer_name, subject: b.subject, description: b.description } }];

