// Recoge la salida estructurada del agente y el audit_id que devolvió la herramienta de acción.
const r = $input.first().json;
const ctx = $('Comprobar llamada interna').first().json;
const steps = Array.isArray(r.intermediateSteps) ? r.intermediateSteps : [];
const tools = [];
let auditId = null;
for (const s of steps) {
  const tool = s.action?.tool || '';
  if (tool) tools.push(tool);
  if (tool === 'proponer_resolucion_ticket') {
    const obs = typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation || '');
    const m = obs.match(/"audit_id"\s*:\s*(\d+)/);
    if (m) auditId = Number(m[1]);
  }
}
const out = r.output || {};
const consulted = tools.some(t => t === 'consultar_pedido_e_historial_cliente' || t === 'consultar_disponibilidad_almacen');
const problems = [];
if (!auditId) problems.push('el agente no registró la propuesta en el back-office');
if (!consulted && ctx.order_ref) problems.push('el agente no consultó ninguna herramienta antes de proponer');

const msg = [
  '🤖 PROPUESTA DEL AGENTE (pendiente de revisión humana)',
  `Ticket: ${ctx.ticket_ref}  ·  Pedido: ${ctx.order_ref ?? 'sin pedido'}  ·  Propuesta #${auditId ?? '?'}`,
  `Caso: ${out.tipo_caso_detectado}`,
  `Acción propuesta: ${out.accion_propuesta}`,
  `Justificación: ${out.justificacion_breve}`,
  `Confianza/prioridad: ${out.nivel_confianza_o_prioridad}`,
  `⚠️ Riesgos: ${out.riesgos_o_advertencias}`,
  `Herramientas usadas: ${tools.join(', ') || 'ninguna'}`,
  '',
  'Mensaje que recibiría el cliente si apruebas:',
  `«${out.mensaje_propuesto_telegram}»`,
].join('\n');

return [{ json: { ok: problems.length === 0, problems, audit_id: auditId, ticket_ref: ctx.ticket_ref, order_ref: ctx.order_ref, tools, proposal: out, supervisor_message: msg } }];

// Convierte la respuesta del botón de Telegram en la decisión que espera el back-office.
const approved = $input.first().json.data?.approved === true;
const prev = $('Extraer propuesta').first().json;
return [{ json: {
  approved,
  ticket_ref: prev.ticket_ref,
  review: {
    audit_id: prev.audit_id,
    decision: approved ? 'aprobado' : 'rechazado',
    reviewed_by: 'Supervisor (botón de Telegram)',
    comment: 'Decisión tomada desde Telegram (n8n sendAndWait, ejecución ' + $execution.id + ')'
  }
} }];

