// Escenario 3 · Verifica la firma del aviso ai.proposal.approved del back-office (contrato BO, apartado 3.6).
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers;
const secret = $env.ERP_WEBHOOK_SECRET || '';
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const received = headers['x-piquantum-signature'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
const signatureOk = received.length === expected.length
  && crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));

let reason = null;
if (!secret) reason = 'n8n sin ERP_WEBHOOK_SECRET';
else if (!signatureOk) reason = 'firma incorrecta';

let event = null;
try { event = JSON.parse(raw); } catch (e) { reason = reason || 'cuerpo que no es JSON'; }
if (!reason && event.source !== 'piquantum.backoffice.erp') reason = 'source desconocido';
if (!reason && event.event_type !== 'ai.proposal.approved') reason = 'event_type no soportado';
const d = event?.data || {};
if (!reason && !/^-?\d+$/.test(String(d.customer_telegram_chat_id || ''))) reason = 'customer_telegram_chat_id no numérico';
if (!reason && !String(d.customer_message || '').trim()) reason = 'customer_message vacío';

return [{ json: { valid: reason === null, reason, event } }];
